    // InitializeMultiline sets default options implied by Multiline.
    void rec::InitializeMultiline(Struct* s)
    {
        if(! rec::Has(gocpp::recv(s->Flags), jsonflags::SpaceAfterColon))
        {
            rec::Set(gocpp::recv(s->Flags), jsonflags::SpaceAfterColon | 1);
        }
        if(! rec::Has(gocpp::recv(s->Flags), jsonflags::SpaceAfterComma))
        {
            rec::Set(gocpp::recv(s->Flags), jsonflags::SpaceAfterComma | 0);
        }
        if(! rec::Has(gocpp::recv(s->Flags), jsonflags::Indent))
        {
            rec::Set(gocpp::recv(s->Flags), jsonflags::Indent | 1);
            s->CoderValues.Indent = "\t"_s;
        }
    }

    // ChangedWhitespace reports whether whitespace values have changed.
    bool ChangedWhitespace(Struct s1, Struct s2)
    {
        return rec::Get(gocpp::recv(s1.Flags), jsonflags::Multiline) != rec::Get(gocpp::recv(s2.Flags), jsonflags::Multiline) ||
                rec::Get(gocpp::recv(s1.Flags), jsonflags::SpaceAfterColon) != rec::Get(gocpp::recv(s2.Flags), jsonflags::SpaceAfterColon) ||
                rec::Get(gocpp::recv(s1.Flags), jsonflags::SpaceAfterComma) != rec::Get(gocpp::recv(s2.Flags), jsonflags::SpaceAfterComma) ||
                (rec::Get(gocpp::recv(s2.Flags), jsonflags::Multiline) && (s1.CoderValues.Indent != s2.CoderValues.Indent || s1.CoderValues.IndentPrefix != s2.CoderValues.IndentPrefix));
    }

